//! Unicode decimal digits, which Python accepts in `int()` and `Decimal()`.

// BEGIN GENERATED by tests/parity/generate_unicode_tables.py
/// First code point of every block of ten decimal digits (Unicode category Nd) in
/// Unicode 16.0.0, the version of Python 3.14. Every block holds the digits 0 to 9 in
/// order, so a digit's value is its distance from the start of its block. Generated
/// with `unicodedata`; the blocks cover all 760 Nd characters.
const DIGIT_ZEROS: [u32; 76] = [
    0x00030, 0x00660, 0x006F0, 0x007C0, 0x00966, 0x009E6, 0x00A66, 0x00AE6, 0x00B66, 0x00BE6,
    0x00C66, 0x00CE6, 0x00D66, 0x00DE6, 0x00E50, 0x00ED0, 0x00F20, 0x01040, 0x01090, 0x017E0,
    0x01810, 0x01946, 0x019D0, 0x01A80, 0x01A90, 0x01B50, 0x01BB0, 0x01C40, 0x01C50, 0x0A620,
    0x0A8D0, 0x0A900, 0x0A9D0, 0x0A9F0, 0x0AA50, 0x0ABF0, 0x0FF10, 0x104A0, 0x10D30, 0x10D40,
    0x11066, 0x110F0, 0x11136, 0x111D0, 0x112F0, 0x11450, 0x114D0, 0x11650, 0x116C0, 0x116D0,
    0x116DA, 0x11730, 0x118E0, 0x11950, 0x11BF0, 0x11C50, 0x11D50, 0x11DA0, 0x11F50, 0x16130,
    0x16A60, 0x16AC0, 0x16B50, 0x16D70, 0x1CCF0, 0x1D7CE, 0x1D7D8, 0x1D7E2, 0x1D7EC, 0x1D7F6,
    0x1E140, 0x1E2F0, 0x1E4F0, 0x1E5F1, 0x1E950, 0x1FBF0,
];
// END GENERATED

/// The value of a decimal digit in any script, like Python's `unicodedata.decimal`.
pub fn decimal_digit(character: char) -> Option<u8> {
    let code = u32::from(character);
    let block = match DIGIT_ZEROS.binary_search(&code) {
        Ok(index) => index,
        Err(0) => return None,
        Err(index) => index - 1,
    };
    let offset = code.checked_sub(*DIGIT_ZEROS.get(block)?)?;
    u8::try_from(offset).ok().filter(|digit| *digit < 10)
}

/// Replaces decimal digits of any script with ASCII digits.
pub fn to_ascii_digits(text: &str) -> String {
    text.chars()
        .map(|character| match decimal_digit(character) {
            Some(digit) => char::from(b'0' + digit),
            None => character,
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_digits_of_other_scripts() {
        assert_eq!(decimal_digit('7'), Some(7));
        assert_eq!(decimal_digit('\u{0662}'), Some(2)); // Arabic-Indic two
        assert_eq!(decimal_digit('\u{FF19}'), Some(9)); // fullwidth nine
        assert_eq!(decimal_digit('\u{1FBF0}'), Some(0)); // segmented zero
        assert_eq!(decimal_digit('\u{1FBF9}'), Some(9));
        assert_eq!(decimal_digit('a'), None);
        assert_eq!(decimal_digit('\u{00B2}'), None); // superscript two is not Nd
        assert_eq!(decimal_digit('\u{1FBFA}'), None);
        assert_eq!(to_ascii_digits("\u{FF11}\u{FF12}.\u{FF15}0"), "12.50");
    }

    #[test]
    fn the_table_is_sorted_and_blocks_do_not_overlap() {
        assert!(DIGIT_ZEROS.windows(2).all(|pair| pair[0] + 10 <= pair[1]));
    }
}
